// Encryption of browser-local data (REQ §7.5, ARCHITECTURE A5; ADR 0019). One AES-256-GCM key
// per browser profile, generated by Web Crypto as non-extractable and kept in IndexedDB, so
// script can use it but never read its bytes. Each value is sealed with a fresh 96-bit IV and
// bound to its record name as associated data, so sealed values cannot be swapped between
// records. Weaker than a phone keystore: anyone running script on this origin, or with access
// to the unlocked browser profile, can use the key; the UI says so.
import type { PingdostDb, SealedRow, VaultKey } from './db';

const VAULT_KEY_ID = 'vault';
const AAD_PREFIX = 'pingdost/web-record/v1\u0000';
const IV_BYTES = 12;

const encoder = new TextEncoder();
const decoder = new TextDecoder();

export interface Sealed {
  iv: Uint8Array;
  data: Uint8Array;
}

/** This browser's vault key, created on first use. */
export async function vaultKey(db: PingdostDb): Promise<VaultKey> {
  const existing = await db.keys.get(VAULT_KEY_ID);
  if (existing) return existing.key;
  const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, [
    'encrypt',
    'decrypt',
  ]);
  // Another tab may have stored one first: everyone uses the first.
  await db.transaction('rw', db.keys, async () => {
    if (!(await db.keys.get(VAULT_KEY_ID))) await db.keys.add({ id: VAULT_KEY_ID, key });
  });
  return (await db.keys.get(VAULT_KEY_ID))!.key;
}

const aad = (context: string) => encoder.encode(AAD_PREFIX + context);

export async function encryptBytes(
  key: VaultKey,
  plaintext: Uint8Array,
  context: string,
): Promise<Sealed> {
  const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES));
  const data = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv, additionalData: aad(context) },
    key,
    plaintext as Uint8Array<ArrayBuffer>,
  );
  return { iv, data: new Uint8Array(data) };
}

/** Throws (`OperationError`) if the value was altered or belongs to another record. */
export async function decryptBytes(
  key: VaultKey,
  sealed: Sealed,
  context: string,
): Promise<Uint8Array> {
  const plaintext = await crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: sealed.iv as Uint8Array<ArrayBuffer>, additionalData: aad(context) },
    key,
    sealed.data as Uint8Array<ArrayBuffer>,
  );
  return new Uint8Array(plaintext);
}

/** Seals a JSON value (bytes inside it must be base64 first). */
export function encryptRecord(key: VaultKey, value: unknown, context: string): Promise<Sealed> {
  return encryptBytes(key, encoder.encode(JSON.stringify(value)), context);
}

export async function decryptRecord<T>(key: VaultKey, sealed: Sealed, context: string): Promise<T> {
  return JSON.parse(decoder.decode(await decryptBytes(key, sealed, context))) as T;
}

/** Sealed JSON values by name in the `records` table. */
export class SealedRecords {
  constructor(
    private readonly db: PingdostDb,
    private readonly key: VaultKey,
  ) {}

  async get<T>(id: string): Promise<T | undefined> {
    const row = await this.db.records.get(id);
    return row ? decryptRecord<T>(this.key, row, id) : undefined;
  }

  async put(id: string, value: unknown): Promise<void> {
    const sealed = await encryptRecord(this.key, value, id);
    const row: SealedRow = { id, ...sealed };
    await this.db.records.put(row);
  }

  async delete(id: string): Promise<void> {
    await this.db.records.delete(id);
  }
}
